// ── Color support (zero-dependency) ───────────────────────────────────────────
// Respects NO_COLOR, FORCE_COLOR, and TTY detection for CI compatibility.

function supportsColor() {
  if (process.env.NO_COLOR || process.env.NO_COLOR === "") return false;
  if (process.env.FORCE_COLOR && process.env.FORCE_COLOR !== "0") return true;
  return !!(process.stdout && process.stdout.isTTY);
}

function makeColor(open, close) {
  return (text) => {
    if (!supportsColor()) return text;
    return `\x1b[${open}m${text}\x1b[${close}m`;
  };
}

const c = {
  bold: makeColor(1, 22),
  dim: makeColor(2, 22),
  red: makeColor(31, 39),
  green: makeColor(32, 39),
  yellow: makeColor(33, 39),
  blue: makeColor(34, 39),
  gray: makeColor(90, 39),
};

// ── Progress spinner (zero-dependency, interactive TTY only) ──────────────────
// Writes to stderr so stdout stays clean for piping / JSON parsing.
// Respects the same color/TTY rules as the rest of the CLI.

function supportsSpinner() {
  if (process.env.NO_COLOR || process.env.NO_COLOR === "") return false;
  if (process.env.FORCE_COLOR && process.env.FORCE_COLOR !== "0") return true;
  return !!(process.stderr && process.stderr.isTTY);
}

const SPINNER_FRAMES = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

function createSpinner(label) {
  if (!supportsSpinner()) {
    // No-op spinner for non-TTY / CI — same API, zero side-effects.
    return {
      start() {},
      stop(msg) {
        if (msg) console.error(msg);
      },
      fail(msg) {
        if (msg) console.error(msg);
      },
    };
  }

  let intervalId = null;
  let frameIdx = 0;
  const text = label || "Loading";

  function render() {
    const frame = SPINNER_FRAMES[frameIdx % SPINNER_FRAMES.length];
    process.stderr.write(`\x1b[2K\r${c.dim(frame)} ${text}…`);
    frameIdx++;
  }

  return {
    start() {
      if (intervalId) return;
      frameIdx = 0;
      render();
      intervalId = setInterval(render, 80);
    },
    stop(msg) {
      if (intervalId) {
        clearInterval(intervalId);
        intervalId = null;
      }
      if (msg) {
        process.stderr.write(`\x1b[2K\r${msg}\n`);
      } else {
        process.stderr.write("\x1b[2K\r");
      }
    },
    fail(msg) {
      if (intervalId) {
        clearInterval(intervalId);
        intervalId = null;
      }
      if (msg) {
        process.stderr.write(`\x1b[2K\r${c.red("✗")} ${msg}\n`);
      } else {
        process.stderr.write("\x1b[2K\r");
      }
    },
  };
}

