class CliUsageError extends Error {}

async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

async function readIntentSource(intentArg) {
  if (!intentArg) {
    throw new CliUsageError("--intent is required (path to JSON file, or - for stdin)");
  }
  if (intentArg === "-") {
    const text = await readStdin();
    if (!text.trim()) throw new CliUsageError("--intent - : stdin was empty");
    return text;
  }
  const { readFileSync, existsSync } = await import("node:fs");
  if (!existsSync(intentArg)) {
    throw new CliUsageError(`--intent file not found: ${intentArg}`);
  }
  return readFileSync(intentArg, "utf8");
}

function parseIntentJson(text) {
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    throw new CliUsageError(`--intent JSON is malformed: ${e.message}`);
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new CliUsageError("--intent JSON must be an object (ActionIntent shape)");
  }
  return parsed;
}

function resolveBaseUrl(flagValue) {
  return (flagValue || process.env.TFA_BASE_URL || "http://localhost:3000").replace(/\/$/, "");
}

function resolveTenant(flagValue, intentBody) {
  return flagValue || process.env.TFA_TENANT_ID || intentBody.tenantId || null;
}

function resolveApiKey(flagValue) {
  return flagValue || process.env.TFA_API_KEY || null;
}

/** POST the intent to /api/adapter/run. Returns { status, body } or throws CliNetworkError. */
class CliNetworkError extends Error {}

async function postAdapterRun(baseUrl, tenantId, apiKey, intentBody) {
  const headers = {
    "content-type": "application/json",
    "idempotency-key": `tfa-cli-${intentBody.nonce || Date.now()}-${Math.random().toString(36).slice(2)}`,
  };
  if (apiKey) headers["x-api-key"] = apiKey;
  else if (tenantId) headers["x-tenant-id"] = tenantId;

  let res;
  try {
    res = await fetch(`${baseUrl}/api/adapter/run`, {
      method: "POST",
      headers,
      body: JSON.stringify(intentBody),
    });
  } catch (e) {
    throw new CliNetworkError(`could not reach ${baseUrl}: ${e.message}`);
  }
  const text = await res.text();
  let body;
  try { body = JSON.parse(text); } catch { body = { _raw: text }; }
  if (res.status >= 500) {
    throw new CliNetworkError(`TFA server error (${res.status}): ${JSON.stringify(body)}`);
  }
  return { status: res.status, body };
}

function decisionColor(decision) {
  if (decision === "allowed") return c.green(decision);
  if (decision === "denied") return c.red(decision);
  if (decision === "approval_required") return c.yellow(decision);
  return c.gray(String(decision));
}

function printHumanSummary(status, body) {
  const decision = body?.decision ?? "(unknown)";
  console.log(`${c.bold("TFA decision:")} ${decisionColor(decision)}`);
  if (body?.receipt) {
    console.log(`  ${c.dim("intentId:")}        ${body.receipt.intentId ?? "-"}`);
    console.log(`  ${c.dim("riskClass:")}       ${body.receipt.riskClass ?? "-"}`);
    console.log(`  ${c.dim("approvalClass:")}   ${body.receipt.approvalClass ?? "-"}`);
    if (body.receipt.executionId) console.log(`  ${c.dim("executionId:")}     ${body.receipt.executionId}`);
    if (body.receipt.approvalToken) console.log(`  ${c.dim("approvalToken:")}   ${body.receipt.approvalToken}`);
    console.log(`  ${c.dim("issuedAt:")}        ${body.receipt.issuedAt ?? "-"}`);
  }
  if (status >= 400 && body?.error) {
    console.log(`  ${c.red("error:")} ${body.error}`);
  }
}

function exitCodeForDecision(decision) {
  if (decision === "allowed") return EXIT_ALLOWED;
  if (decision === "approval_required") return EXIT_APPROVAL_REQUIRED;
  if (decision === "denied") return EXIT_DENIED;
  return EXIT_NETWORK_ERROR; // unrecognised/missing decision on a 2xx response is treated as an error
}

async function runCheckAction(opts) {
  const text = await readIntentSource(opts.intent);
  const intentBody = parseIntentJson(text);

  const baseUrl = resolveBaseUrl(opts.baseUrl);
  const apiKey = resolveApiKey(opts.apiKey);
  const tenantId = resolveTenant(opts.tenant, intentBody);
  if (!apiKey && !tenantId) {
    throw new CliUsageError("no tenant: supply --tenant, set TFA_TENANT_ID, or include tenantId in the intent JSON (or use --api-key)");
  }

  const spinner = opts.json ? { start() {}, stop() {}, fail() {} } : createSpinner("Contacting TFA");
  if (!opts.json) spinner.start();
  try {
    const { status, body } = await postAdapterRun(baseUrl, tenantId, apiKey, intentBody);
    spinner.stop();

    if (opts.json) {
      console.log(JSON.stringify(body, null, 2));
    } else {
      printHumanSummary(status, body);
    }

    if (status >= 400) {
      return EXIT_NETWORK_ERROR;
    }
    return exitCodeForDecision(body?.decision);
  } catch (e) {
    spinner.fail(e instanceof CliNetworkError ? e.message : "Request failed");
    throw e;
  }
}

async function main() {
  let opts;
  try {
    opts = parseArgs(process.argv.slice(2));
  } catch (e) {
    if (e instanceof CliUsageError) {
      console.error(`tfa: ${e.message}`);
      console.error(`Run "tfa --help" for usage.`);
      process.exitCode = EXIT_USAGE_ERROR;
      return;
    }
    throw e;
  }

  // --no-color is processed as a side-effect before any command runs.
  if (opts.noColor) {
    process.env.NO_COLOR = "1";
  }

  if (opts.help || opts.command === null && !opts.version) {
    printHelp();
    process.exitCode = opts.command === null && !opts.help && !opts.version ? EXIT_USAGE_ERROR : EXIT_ALLOWED;
    return;
  }
  if (opts.version) {
    console.log(VERSION);
    process.exitCode = EXIT_ALLOWED;
    return;
  }

  const commandHandlers = {
    "check-action": runCheckAction,
    "start": runStart,
    "receipt": runReceipt,
    "verify": runVerify,
  };
  if (opts.command && commandHandlers[opts.command]) {
    try {
      process.exitCode = await commandHandlers[opts.command](opts);
    } catch (e) {
      if (e instanceof CliUsageError) {
        console.error(`tfa ${opts.command}: ${e.message}`);
        process.exitCode = EXIT_USAGE_ERROR;
      } else if (e instanceof CliNetworkError) {
        console.error(`tfa ${opts.command}: ${e.message}`);
        process.exitCode = EXIT_NETWORK_ERROR;
      } else {
        console.error(`tfa ${opts.command}: unexpected error: ${e.message}`);
        process.exitCode = EXIT_NETWORK_ERROR;
      }
    }
    return;
  }

  console.error(`tfa: unknown command "${opts.command}"`);
  console.error(`Run "tfa --help" for usage.`);
  process.exitCode = EXIT_USAGE_ERROR;
}

// Only run main() when executed directly (not when imported for testing).
const isMain = import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  main();
}

