// ─── tfa start ───────────────────────────────────────────────────────────────
// Post an ActionIntent and return the executionId / approvalToken for polling.
// This is `check-action` but without blocking — it prints IDs for follow-up
// with `tfa receipt --workflow-id <id>`.

export async function runStart(opts) {
  const text = await readIntentSource(opts.intent);
  const intentBody = parseIntentJson(text);

  const baseUrl = resolveBaseUrl(opts.baseUrl);
  const apiKey = resolveApiKey(opts.apiKey);
  const tenantId = resolveTenant(opts.tenant, intentBody);
  if (!apiKey && !tenantId) {
    throw new CliUsageError("no tenant: supply --tenant, set TFA_TENANT_ID, or include tenantId in the intent JSON (or use --api-key)");
  }

  const spinner = opts.json ? { start() {}, stop() {}, fail() {} } : createSpinner("Starting action");
  if (!opts.json) spinner.start();
  try {
    const { status, body } = await postAdapterRun(baseUrl, tenantId, apiKey, intentBody);
    spinner.stop();

    if (opts.json) {
      console.log(JSON.stringify(body, null, 2));
    } else {
      const decision = body?.decision ?? "(unknown)";
      console.log(`${c.bold("TFA start:")} decision=${decisionColor(decision)}`);
      if (body?.receipt) {
        const r = body.receipt;
        if (r.executionId)    console.log(`  ${c.dim("executionId:")}     ${r.executionId}`);
        if (r.approvalToken)  console.log(`  ${c.dim("approvalToken:")}   ${r.approvalToken}`);
        if (r.riskClass)      console.log(`  ${c.dim("riskClass:")}       ${r.riskClass}`);
        if (r.approvalClass)  console.log(`  ${c.dim("approvalClass:")}   ${r.approvalClass}`);
        console.log(`  ${c.dim("issuedAt:")}        ${r.issuedAt ?? "-"}`);
        // Print the ID for easy piping / scripting.
        const workflowId = r.approvalToken ?? r.executionId;
        if (workflowId && !opts.json) {
          console.log(`\n${c.dim("Poll receipt:")}  tfa receipt --workflow-id ${workflowId}`);
        }
      }
      if (status >= 400 && body?.error) console.log(`  ${c.red("error:")} ${body.error}`);
    }

    if (status >= 400) return EXIT_NETWORK_ERROR;
    return exitCodeForDecision(body?.decision);
  } catch (e) {
    spinner.fail(e instanceof CliNetworkError ? e.message : "Request failed");
    throw e;
  }
}

// ─── tfa receipt ─────────────────────────────────────────────────────────────
// Fetch GET /api/execution/{id}/receipt, print the signed status receipt,
// and optionally verify the signature offline (HMAC with --secret, or
// Ed25519 with --public-key in SPKI PEM format).

export async function runReceipt(opts) {
  if (!opts.workflowId) {
    throw new CliUsageError("--workflow-id is required (executionId or approvalToken)");
  }

  const baseUrl = resolveBaseUrl(opts.baseUrl);
  const apiKey = resolveApiKey(opts.apiKey);
  const tenantId = opts.tenant || process.env.TFA_TENANT_ID || null;
  if (!apiKey && !tenantId) {
    throw new CliUsageError("no tenant: supply --tenant or set TFA_TENANT_ID (or use --api-key)");
  }

  const headers = {};
  if (apiKey) headers["x-api-key"] = apiKey;
  else if (tenantId) headers["x-tenant-id"] = tenantId;

  const spinner = opts.json ? { start() {}, stop() {}, fail() {} } : createSpinner("Fetching receipt");
  if (!opts.json) spinner.start();

  let res;
  try {
    res = await fetch(`${baseUrl}/api/execution/${encodeURIComponent(opts.workflowId)}/receipt`, { headers });
  } catch (e) {
    spinner.fail(e.message);
    throw new CliNetworkError(`could not reach ${baseUrl}: ${e.message}`);
  }

  const text = await res.text();
  let body;
  try { body = JSON.parse(text); } catch { body = { _raw: text }; }

  if (res.status === 404) {
    spinner.fail(`workflow not found (404): ${opts.workflowId}`);
    throw new CliNetworkError(`workflow not found or access denied (404): ${opts.workflowId}`);
  }
  if (res.status >= 500) {
    spinner.fail(`server error (${res.status})`);
    throw new CliNetworkError(`TFA server error (${res.status}): ${JSON.stringify(body)}`);
  }

  spinner.stop();

  if (opts.json) {
    console.log(JSON.stringify(body, null, 2));
    return res.status < 400 ? EXIT_ALLOWED : EXIT_NETWORK_ERROR;
  }

  const receipt = body?.receipt;
  const workflow = body?.workflow;
  if (!receipt) {
    console.log(JSON.stringify(body, null, 2));
    return res.status < 400 ? EXIT_ALLOWED : EXIT_NETWORK_ERROR;
  }

  console.log(c.bold("TFA status receipt:"));
  console.log(`  ${c.dim("executionId:")}   ${receipt.executionId ?? "-"}`);
  console.log(`  ${c.dim("tenantId:")}      ${receipt.tenantId ?? "-"}`);
  console.log(`  ${c.dim("status:")}        ${receipt.status ?? "-"}`);
  console.log(`  ${c.dim("actorId:")}       ${receipt.actorId ?? "-"}`);
  console.log(`  ${c.dim("runLogLength:")}  ${receipt.runLogLength ?? "-"}`);
  console.log(`  ${c.dim("issuedAt:")}      ${receipt.issuedAt ?? "-"}`);
  console.log(`  ${c.dim("signature:")}     ${receipt.signature ?? "-"}`);
  if (workflow?.actionId)  console.log(`  ${c.dim("actionId:")}      ${workflow.actionId}`);

  // ── Offline verification ──────────────────────────────────────────────────
  // Reconstruct the canonical payload and verify the signature locally.
  // Supports HMAC-SHA256 (--secret) and Ed25519 (--public-key SPKI PEM).
  // This mirrors lib/adapter/agent-adapter.ts canonicalStatusReceiptPayload().
  if (opts.secret || opts.publicKey) {
    const payload = [
      receipt.version ?? "tfa-status-receipt-v1",
      receipt.executionId,
      receipt.tenantId,
      receipt.status,
      receipt.actorId,
      String(receipt.runLogLength),
      receipt.issuedAt,
    ].join("|");

    let verified = false;
    let verifyError = null;
    try {
      if (opts.secret) {
        // HMAC-SHA256 verification using Node.js built-in crypto.
        const { createHmac } = await import("node:crypto");
        const expected = createHmac("sha256", opts.secret).update(payload).digest("base64");
        verified = expected === receipt.signature;
      } else if (opts.publicKey) {
        // Ed25519 verification using Node.js built-in crypto.
        const { createVerify, createPublicKey } = await import("node:crypto");
        const keyObj = createPublicKey(opts.publicKey);
        const v = createVerify("SHA-256");
        v.update(payload);
        // signature is base64-encoded raw bytes.
        verified = v.verify(keyObj, receipt.signature, "base64");
      }
    } catch (e) {
      verifyError = e.message;
    }

    if (verifyError) {
      console.log(`\n${c.red("offline verification: ERROR")} — ${verifyError}`);
      return EXIT_NETWORK_ERROR;
    }
    console.log(`\n${verified ? c.green("offline verification: ✓ VALID") : c.red("offline verification: ✗ INVALID (signature mismatch)")}`);
    if (!verified) return EXIT_NETWORK_ERROR;
  } else {
    console.log(c.dim("\n(pass --secret or --public-key to verify the signature offline)"));
  }

  return EXIT_ALLOWED;
}

// ─── tfa verify ──────────────────────────────────────────────────────────────
// POST a signed receipt to /api/receipt/verify and print the authoritative verdict.
// Supports optional AP2 mandate linkage for full-chain verification.

async function runVerify(opts) {
  if (!opts.receipt) {
    throw new CliUsageError("--receipt is required (path to receipt JSON, or - for stdin)");
  }

  const receiptText = await readIntentSource(opts.receipt);
  let receiptBody;
  try {
    receiptBody = JSON.parse(receiptText);
  } catch (e) {
    throw new CliUsageError(`--receipt JSON is malformed: ${e.message}`);
  }
  if (typeof receiptBody !== "object" || receiptBody === null || Array.isArray(receiptBody)) {
    throw new CliUsageError("--receipt JSON must be an object (receipt shape)");
  }

  let mandateLinkage;
  if (opts.mandateLinkage) {
    const { readFileSync, existsSync } = await import("node:fs");
    if (!existsSync(opts.mandateLinkage)) {
      throw new CliUsageError(`--mandate-linkage file not found: ${opts.mandateLinkage}`);
    }
    const linkageText = readFileSync(opts.mandateLinkage, "utf8");
    try {
      mandateLinkage = JSON.parse(linkageText);
    } catch (e) {
      throw new CliUsageError(`--mandate-linkage JSON is malformed: ${e.message}`);
    }
  }

  const baseUrl = resolveBaseUrl(opts.baseUrl);
  const apiKey = resolveApiKey(opts.apiKey);
  const tenantId = opts.tenant || process.env.TFA_TENANT_ID || null;
  if (!apiKey && !tenantId) {
    throw new CliUsageError("no tenant: supply --tenant or set TFA_TENANT_ID (or use --api-key)");
  }

  const headers = {
    "content-type": "application/json",
    "idempotency-key": `tfa-cli-verify-${Date.now()}-${Math.random().toString(36).slice(2)}`,
  };
  if (apiKey) headers["x-api-key"] = apiKey;
  else if (tenantId) headers["x-tenant-id"] = tenantId;

  const postBody = { receipt: receiptBody };
  if (mandateLinkage !== undefined) postBody.mandateLinkage = mandateLinkage;

  const spinner = opts.json ? { start() {}, stop() {}, fail() {} } : createSpinner("Verifying receipt");
  if (!opts.json) spinner.start();

  let res;
  try {
    res = await fetch(`${baseUrl}/api/receipt/verify`, {
      method: "POST",
      headers,
      body: JSON.stringify(postBody),
    });
  } catch (e) {
    spinner.fail(e.message);
    throw new CliNetworkError(`could not reach ${baseUrl}: ${e.message}`);
  }

  const text = await res.text();
  let body;
  try { body = JSON.parse(text); } catch { body = { _raw: text }; }

  if (res.status >= 500) {
    spinner.fail(`server error (${res.status})`);
    throw new CliNetworkError(`TFA server error (${res.status}): ${JSON.stringify(body)}`);
  }

  spinner.stop();

  if (opts.json) {
    console.log(JSON.stringify(body, null, 2));
    return body?.valid === true ? EXIT_ALLOWED : EXIT_DENIED;
  }

  const valid = body?.valid === true;
  const signatureValid = body?.signatureValid;
  const decisionValid = body?.decisionValid;
  const mandateLinkageValid = body?.mandateLinkageValid;
  const reasons = body?.reasons || [];

  console.log(`${c.bold("TFA receipt verification:")} ${valid ? c.green("✓ VALID") : c.red("✗ INVALID")}`);
  console.log(`  ${c.dim("signatureValid:")}   ${signatureValid ?? "-"}`);
  console.log(`  ${c.dim("decisionValid:")}    ${decisionValid ?? "-"}`);
  if (mandateLinkageValid !== undefined) {
    console.log(`  ${c.dim("mandateLinkageValid:")} ${mandateLinkageValid}`);
  }
  if (reasons.length > 0) {
    console.log(`  ${c.yellow("reasons:")}`);
    for (const r of reasons) console.log(`    - ${c.yellow(r)}`);
  }

  return valid ? EXIT_ALLOWED : EXIT_DENIED;
}

